def mode_for_template(mode="auto", filename=None):
    """Resolve the auto mode from a template path's extension."""
    if mode != "auto":
        return mode
    ext = os.path.splitext(filename)[1] if filename else ""
    if ext in (".html", ".htm", ".xml", ".xhtml"):
        return "html"
    if ext in (".json", ".json5", ".yaml", ".yml"):
