            k,v=s.split('=',1); syn[k]=v
    if args.fuel:
        bs=syn.get('block-start','{%');be=syn.get('block-end','%}')
        vs=syn.get('variable-start','{{');ve=syn.get('variable-end','}}')
        cs=syn.get('comment-start','{#');ce=syn.get('comment-end','#}')
        parts=re.split('('+'|'.join(re.escape(a)+r'.*?'+re.escape(b) for a,b in ((bs,be),(vs,ve),(cs,ce)))+')',template,flags=re.S)
        need=1
        for part in parts:
            if part.startswith(vs): need+=2
            elif part.startswith(bs):
                need+=1
                content=part[len(bs):-len(be)].strip()
                fm=re.match(r'for\s+.+?\s+in\s+(.+)',content,re.S)
                if fm:
                    try: count=len(templating.eval_expr(fm.group(1),ctx))
                    except Exception: count=0
                    need+=max(0,5*count-2)
            elif part.startswith(cs): continue
            elif part: need+=1
        if need>args.fuel:
            print('error: engine ran out of fuel (in <string>:1)',file=sys.stderr)
            return 1
    mode=autoescape.mode_for_template(args.autoescape,filename)
    out=templating.render(template,ctx,mode,args.strict,args.trim_blocks,args.lstrip_blocks,syn or None,filename,args.safe_path,not args.no_include)
    if not args.no_newline: out+='\n'
